package logintake

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"strings"
	"time"
)

type Record struct {
	ExecutionID string `json:"execution_id"`
	StartedAt   string `json:"started_at"`
	Status      string `json:"status"`
	Job         struct {
		CommandName string `json:"command_name"`
		Target      string `json:"target"`
		LLM         string `json:"llm"`
		Model       string `json:"model"`
	} `json:"job"`
	Result struct {
		Returncode *int `json:"returncode"`
		TimedOut   bool `json:"timed_out"`
		Stats      struct {
			InputTokens       int64   `json:"input_tokens"`
			CachedInputTokens int64   `json:"cached_input_tokens"`
			OutputTokens      int64   `json:"output_tokens"`
			ElapsedMS         int64   `json:"elapsed_ms"`
			CostUSD           float64 `json:"cost_usd"`
			Model             string  `json:"model"`
		} `json:"stats"`
	} `json:"result"`
}

type Filters struct{ Target, Since, Until string }

func Read(r io.Reader, warn func(line int, err error)) ([]Record, int, error) {
	s := bufio.NewScanner(r)
	s.Buffer(make([]byte, 64*1024), 16*1024*1024)
	seen := map[string]bool{}
	var records []Record
	skipped, line := 0, 0
	for s.Scan() {
		line++
		b := s.Bytes()
		if strings.TrimSpace(string(b)) == "" {
			continue
		}
		var raw map[string]json.RawMessage
		var rec Record
		err := json.Unmarshal(b, &raw)
		if err == nil && raw == nil {
			err = fmt.Errorf("record must be an object")
		}
		if err == nil {
			err = json.Unmarshal(b, &rec)
		}
		if err == nil && (rec.ExecutionID == "" || rec.StartedAt == "" || rec.Status == "" || rec.Job.CommandName == "" || rec.Job.Target == "") {
			err = fmt.Errorf("record is incomplete")
		}
		if err == nil && seen[rec.ExecutionID] {
			err = fmt.Errorf("duplicate execution_id")
		}
		if err != nil {
			skipped++
			if warn != nil {
				warn(line, err)
			}
			continue
		}
		seen[rec.ExecutionID] = true
		records = append(records, rec)
	}
	if err := s.Err(); err != nil {
		return nil, skipped, err
	}
	return records, skipped, nil
}

func Apply(records []Record, f Filters) ([]Record, error) {
	for _, d := range []string{f.Since, f.Until} {
		if d != "" {
			if _, err := time.Parse("2006-01-02", d); err != nil {
				return nil, fmt.Errorf("invalid date %q", d)
			}
		}
	}
	out := make([]Record, 0, len(records))
	for _, r := range records {
		date := r.StartedAt
		if len(date) < 10 {
			continue
		}
		date = date[:10]
		if f.Target != "" && r.Job.Target != f.Target {
			continue
		}
		if f.Since != "" && date < f.Since {
			continue
		}
		if f.Until != "" && date > f.Until {
			continue
		}
		out = append(out, r)
	}
	return out, nil
}
package cli

import (
	"flag"
	"fmt"
	"io"
	"os"
	"time"

	"drydockstats/internal/logintake"
	"drydockstats/internal/reports"
)

var reportNames = map[string]bool{"summary": true, "commands": true, "targets": true, "models": true, "daily": true, "failures": true}

func Run(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 || !reportNames[args[0]] {
		fmt.Fprintln(stderr, "usage: ddkstat <report> [--target NAME] [--since DATE] [--until DATE] LOG")
		return 2
	}
	fs := flag.NewFlagSet("ddkstat", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	target := fs.String("target", "", "")
	since := fs.String("since", "", "")
	until := fs.String("until", "", "")
	if err := fs.Parse(args[1:]); err != nil {
		fmt.Fprintln(stderr, "invalid arguments")
		return 2
	}
	rest := fs.Args()
	if len(rest) != 1 {
		fmt.Fprintln(stderr, "expected exactly one log path")
		return 2
	}
	for _, d := range []string{*since, *until} {
		if d != "" {
			x, err := time.Parse("2006-01-02", d)
			if err != nil || x.Format("2006-01-02") != d {
				fmt.Fprintln(stderr, "invalid date")
				return 2
			}
		}
	}
	file, err := os.Open(rest[0])
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	defer file.Close()
	records, skipped, err := logintake.Read(file, func(n int, e error) { fmt.Fprintf(stderr, "warning: line %d: %v\n", n, e) })
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	filtered, err := logintake.Apply(records, logintake.Filters{Target: *target, Since: *since, Until: *until})
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	if err := reports.Write(stdout, args[0], filtered, skipped); err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	return 0
}
package reports

import (
	"encoding/csv"
	"fmt"
	"io"
	"sort"
	"strconv"

	"drydockstats/internal/logintake"
)

type totals struct {
	calls, failed, input, cached, output, elapsed int64
	cost                                          float64
}

func (t *totals) add(r logintake.Record) {
	t.calls++
	if r.Status != "succeeded" {
		t.failed++
	}
	t.input += r.Result.Stats.InputTokens
	t.cached += r.Result.Stats.CachedInputTokens
	t.output += r.Result.Stats.OutputTokens
	t.elapsed += r.Result.Stats.ElapsedMS
	t.cost += r.Result.Stats.CostUSD
}
func (t totals) minutes() string {
	n := (t.elapsed + 3000) / 6000
	return fmt.Sprintf("%d.%d", n/10, n%10)
}
func num(n int64) string    { return strconv.FormatInt(n, 10) }
func cost(n float64) string { return fmt.Sprintf("%.4f", n) }
func write(w io.Writer, rows [][]string) error {
	c := csv.NewWriter(w)
	c.UseCRLF = false
	for _, r := range rows {
		if err := c.Write(r); err != nil {
			return err
		}
	}
	c.Flush()
	return c.Error()
}

func Write(w io.Writer, name string, rs []logintake.Record, skipped int) error {
	base := totals{}
	for _, r := range rs {
		base.add(r)
	}
	if name == "summary" {
		first, last := "", ""
		for _, r := range rs {
			d := r.StartedAt[:10]
			if first == "" || d < first {
				first = d
			}
			if d > last {
				last = d
			}
		}
		succeeded := base.calls - base.failed
		return write(w, [][]string{{"records", "skipped", "succeeded", "failed", "first", "last", "input_tokens", "cached_tokens", "output_tokens", "cost_usd", "minutes"}, {num(base.calls), strconv.Itoa(skipped), num(succeeded), num(base.failed), first, last, num(base.input), num(base.cached), num(base.output), cost(base.cost), base.minutes()}})
	}
	if name == "failures" {
		failed := make([]logintake.Record, 0)
		for _, r := range rs {
			if r.Status != "succeeded" {
				failed = append(failed, r)
			}
		}
		sort.Slice(failed, func(i, j int) bool {
			if failed[i].StartedAt != failed[j].StartedAt {
				return failed[i].StartedAt < failed[j].StartedAt
			}
			return failed[i].ExecutionID < failed[j].ExecutionID
		})
		rows := [][]string{{"started_at", "target", "command", "model", "returncode", "timed_out"}}
		for _, r := range failed {
			model := r.Result.Stats.Model
			if model == "" {
				model = r.Job.Model
			}
			rc := ""
			if r.Result.Returncode != nil {
				rc = strconv.Itoa(*r.Result.Returncode)
			}
			rows = append(rows, []string{r.StartedAt, r.Job.Target, r.Job.CommandName, model, rc, strconv.FormatBool(r.Result.TimedOut)})
		}
		return write(w, rows)
	}
	groups := map[string]*totals{}
	labels := map[string][]string{}
	for _, r := range rs {
		var key string
		var labs []string
		switch name {
		case "commands":
			key = r.Job.CommandName
			labs = []string{key}
		case "targets":
			key = r.Job.Target
			labs = []string{key}
		case "models":
			m := r.Result.Stats.Model
			if m == "" {
				m = r.Job.Model
			}
			labs = []string{r.Job.LLM, m}
			key = r.Job.LLM + "\x00" + m
		case "daily":
			key = r.StartedAt[:10]
			labs = []string{key}
		default:
			return fmt.Errorf("unknown report %q", name)
		}
		if groups[key] == nil {
			groups[key] = &totals{}
			labels[key] = labs
		}
		groups[key].add(r)
	}
	keys := make([]string, 0, len(groups))
	for k := range groups {
		keys = append(keys, k)
	}
	if name == "commands" {
		sort.Slice(keys, func(i, j int) bool {
			a, b := groups[keys[i]], groups[keys[j]]
			if a.calls != b.calls {
				return a.calls > b.calls
			}
			return keys[i] < keys[j]
		})
	} else {
		sort.Slice(keys, func(i, j int) bool {
			if name == "models" {
				return keys[i] < keys[j]
			}
			return keys[i] < keys[j]
		})
	}
	header := map[string][]string{"commands": {"command", "calls", "failed", "input_tokens", "cached_tokens", "output_tokens", "minutes"}, "targets": {"target", "calls", "failed", "input_tokens", "cached_tokens", "output_tokens", "cost_usd", "minutes"}, "models": {"provider", "model", "calls", "failed", "input_tokens", "cached_tokens", "output_tokens", "cost_usd"}, "daily": {"date", "calls", "failed", "tokens", "minutes"}}[name]
	rows := [][]string{header}
	for _, k := range keys {
		t := groups[k]
		row := append([]string{}, labels[k]...)
		switch name {
		case "commands":
			row = append(row, num(t.calls), num(t.failed), num(t.input), num(t.cached), num(t.output), t.minutes())
		case "targets":
			row = append(row, num(t.calls), num(t.failed), num(t.input), num(t.cached), num(t.output), cost(t.cost), t.minutes())
		case "models":
			row = append(row, num(t.calls), num(t.failed), num(t.input), num(t.cached), num(t.output), cost(t.cost))
		case "daily":
			row = append(row, num(t.calls), num(t.failed), num(t.input+t.cached+t.output), t.minutes())
		}
		rows = append(rows, row)
	}
	row := []string{"TOTAL"}
	switch name {
	case "commands":
		row = append(row, num(base.calls), num(base.failed), num(base.input), num(base.cached), num(base.output), base.minutes())
	case "targets":
		row = append(row, num(base.calls), num(base.failed), num(base.input), num(base.cached), num(base.output), cost(base.cost), base.minutes())
	case "models":
		row = append(row, "", num(base.calls), num(base.failed), num(base.input), num(base.cached), num(base.output), cost(base.cost))
	case "daily":
		row = append(row, num(base.calls), num(base.failed), num(base.input+base.cached+base.output), base.minutes())
	}
	rows = append(rows, row)
	return write(w, rows)
}
